def _invert(x, q, frequency):
    from scipy.optimize import root
    dim = x.shape[1]
    (linear, sine) = (q[1:1 + dim], q[1 + dim:])
    initial = np.linalg.solve(linear.T, (x - q[0]).T).T

    def jac(t):
        return (linear + (frequency * np.cos(frequency * t))[:, None] * sine).T

    def invert_row(observed, guess):

        def fun(t):
            return q[0] + t @ linear + np.sin(frequency * t) @ sine - observed
        fit = root(fun, guess, jac=jac, tol=1e-10)
        if np.linalg.norm(fit.fun, ord=np.inf) > 1e-08:
            from scipy.optimize import least_squares
            fit = least_squares(fun, fit.x, jac=jac, gtol=1e-12)
        return fit.x
    return np.stack([invert_row(obs, guess) for (obs, guess) in zip(x, initial)]) if len(x) else initial

def _features(w, gain, interaction, kind):
    import itertools
    u = gain * w
    if kind == 'atan':
        z = np.arctan(u)
    elif kind == 'inv3':
        z = np.sinh(np.arcsinh(u) / 3)
    else:
        z = np.arcsinh(u)
    if not interaction:
        return np.column_stack((_aff(w), z))
    pairs = [z[:, i] * z[:, j] for (i, j) in itertools.combinations_with_replacement(range(w.shape[1]), 2)]
    return np.column_stack((_aff(w), z, *pairs))

def _predict(w, target, interaction, kind):
    from scipy.optimize import minimize_scalar
    n = len(target)
    scale = np.maximum(np.std(target, axis=0), 1e-08)

    def loss(gain):
        f = _features(w[:n], gain, interaction, kind)
        r = (f @ _ls(f, target) - target) / scale
        return np.mean(r * r)
    gain = minimize_scalar(loss, bounds=(0.8, 7), method='bounded').x
    f = _features(w, gain, interaction, kind)
    return f[n:] @ _ls(f[:n], target)
